var n=`0774-ibihaza`;var t=`world-0774`;var a=`RW`;var s=`eastern-africa`;var r=4;var o=574;var l={en:`Ibihaza`,ua:`Ібіхаза`};var d={en:`Ibihaza is a Rwanda classic prepared with black-eyed peas, pumpkin, yellow onion, tomato. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Ібіхаза, страва кухні країни Руанда зі складниками: квасоля чорноочка, гарбуз, жовта цибуля, помідор. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var g=[{en:`Soak the dried beans or peas in plentiful cold water for 480 minutes, then drain and discard the soaking liquid; keep refrigerated in hot conditions.`,ua:`Замочіть сухі бобові у великій кількості холодної води на 480 хвилин, після чого злийте й вилийте воду від замочування; за спеки тримайте в холодильнику.`,t:[`soaking-legumes`],m:480,i:[[`black-eyed-peas`,240,`g`],[`water`,700,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 55 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 55 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:55,i:[[`water`,950,`ml`]]},{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:12,i:[[`pumpkin`,720,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 24 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 24 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:24,i:[[`yellow-onion`,160,`g`],[`red-palm-oil`,40,`ml`],[`tomato`,240,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,18,`g`],[`table-salt`,null,`to_taste`]]}];var m={slug:n,id:t,country:`RW`,region:s,servings:4,minutes:574,title:l,text:d,steps:g};export{a as country,m as default,t as id,o as minutes,s as region,r as servings,n as slug,g as steps,d as text,l as title};